// Truth Table/State-Transition Table for TopModule
//
// Inputs: clk, shift_ena, count_ena, data
// Outputs: q (4 bits)
//
// clk | shift_ena | count_ena | data | q[3:0]
// ----|----------|----------|------|-------
// 1   | 0        | 0        | X    | same as previous
// 1   | 1        | 0        | X    | data shifted in (MSB first)
// 1   | 0        | 1        | X    | q decremented by 1
// 1   | 1        | 1        | X    | undefined (both shift and count active)

module TopModule (
    input  clk,
    input  shift_ena,
    input  count_ena,
    input  data,
    output reg [3:0] q
);

always @(posedge clk) begin
    if (shift_ena) begin
        q <= {data, q[2:0]};
    end else if (count_ena) begin
        q <= q - 1;
    end
end

endmodule

