module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010
    // 7: 0111
    // 15: 1111
    // SOP expression: a'bc'd + a'bcd + abcd'

    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & !d);

