module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop = (a'c'd') + (a'b'cd) + (a'bcd') + (ab'c'd) + (ab'cd') + (abc'd') + (abcd)
    // Simplified SOP: out_sop = (a'c'd') + (a'b'cd) + (a'bcd') + (ab'c'd) + (ab'cd') + (abc'd') + (abcd)
    // After simplification: out_sop = a'c'd' + a'b'cd + a'bcd' + ab'c'd + ab'cd' + abc'd' + abcd

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos = (a + b + c + d') * (a + b + c' + d) * (a + b' + c + d) * (a + b' + c' + d') * (a' + b + c + d) * (a' + b + c' + d) * (a' + b' + c + d) * (a' + b' + c' + d)
