    // SOP implementation
    assign out_sop = 
        (~a & ~c & ~d) | 
        (~a & ~b & c & d) | 
        (~a & b & c & ~d) | 
        (a & ~b & ~c & d) | 
        (a & ~b & c & ~d) | 
        (a & ~c & b & ~d) | 
        (a & b & c & d);

    // POS implementation
    assign out_pos = 
        (a | b | c | ~d) & 
        (a | b | ~c | d) & 
        (a | ~b | c | d) & 
        (a | ~b | ~c | ~d) & 
        (~a | b | c | d) & 
