// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Output is 0 for all states except D (output is 1 when in state D)

    // Output logic: out = state[3] (since D is 4'b1000)
    assign out = state[3];

    // State transition logic (one-hot encoding)
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // next_state is a 4-bit value

    // State A (0001)
    // in=0: next_state = A (0001)
    // in=1: next_state = B (0010)
    // State A: next_state = (in ? 2'b0010 : 2'b0001)

    // State B (0010)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)
    // State B: next_state = (in ? 2'b0010 : 2'b0100)

    // State C (0100)
    // in=0: next_state = A (0001)
    // in=1: next_state = D (1000)
    // State C: next_state = (in ? 2'b1000 : 2'b0001)

    // State D (1000)
    // in=0: next_state = C (0100)
    // in=1: next_state = B (0010)
    // State D: next_state = (in ? 2'b0010 : 2'b0100)

    // Combine all cases using case statement
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001; // A
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100; // B
            4'b0100: next_state = (in) ? 4'b1000 : 4'b0001; // C
            4'b1000: next_state = (in) ? 4'b0010 : 4'b0100; // D
            default: next_state = 4'b0000;
        endcase
    end

endmodule

