// clk is the clock signal (positive edge-triggered)
// load is synchronous active high (loads data into the register)
// ena[1:0] determines the rotation direction:
//   2'b01: rotate right by 1 bit
//   2'b10: rotate left by 1 bit
//   2'b00 or 2'b11: no rotation
// data is the 100-bit input data
// q is the 100-bit output register

// On each rising edge of clk:
// if load is high, q <= data
// else if ena is 2'b01, rotate right by 1 bit
// else if ena is 2'b10, rotate left by 1 bit
// else, q remains unchanged

module TopModule (
    input  clk,
    input  load,
    input  ena,
    input  data,
    output q
);

// Internal register to hold the 100-bit value
reg [99:0] reg_q;

