    if (load) begin
        reg_q <= data;
    end else begin
        case (ena)
            1'b0: reg_q <= reg_q; // No rotation
            1'b1: begin
                // Rotate right by 1 bit
                reg_q <= {reg_q[98:0], reg_q[99]};
            end
            default: reg_q <= reg_q; // No rotation
        endcase
    end
end

// Output the register value
assign q = reg_q;

endmodule

