// 1 1 1 1 | 1   0

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop = (a'b'c'd) + (a'bc'd') + (a'bcd') + (ab'c'd) + (ab'cd') + (abc'd') + (abcd)
    // Simplified SOP: out_sop = (a'c'd) + (b'c'd') + (a'bc'd) + (ab'c'd) + (abcd)
    // Final SOP: out_sop = a'c'd + b'c'd' + a'bc'd + ab'c'd + abcd

    assign out_sop = (~a & ~c & d) | (~b & ~c & ~d) | (~a & b & ~c & d) | (a & ~b & ~c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos = (a + b + c + d') * (a + b + c' + d) * (a + b' + c + d) * (a' + b + c + d) * (a' + b + c' + d') * (a' + b' + c + d) * (a' + b' + c' + d)
    // Simplified POS: out_pos = (a + b + c + d') * (a + b + c' + d) * (a + b' + c + d) * (a' + b + c + d) * (a' + b' + c + d)
