    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A, B, C, D, E} state_t;

state_t current_state, next_state;
logic [2:0] count;
logic z_out;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        count <= 3'b000;
        z_out <= 1'b0;
    end else begin
        current_state <= next_state;
        if (current_state == A) begin
            if (s) begin
                next_state <= B;
                count <= 3'b000;
            end else begin
                next_state <= A;
            end
        end else if (current_state == B) begin
            if (count < 3) begin
                next_state <= B;
                count <= count + 1;
            end else begin
                next_state <= C;
                count <= 3'b000;
            end
        end else if (current_state == C) begin
            if (count < 3) begin
                next_state <= C;
                count <= count + 1;
            end else begin
                next_state <= D;
                count <= 3'b000;
            end
        end else if (current_state == D) begin
            if (count < 3) begin
                next_state <= D;
                count <= count + 1;
            end else begin
                next_state <= E;
                count <= 3'b000;
            end
        end else if (current_state == E) begin
            next_state <= A;
        end
    end
end

always_comb begin
    case (current_state)
        A: next_state = (s) ? B : A;
        B: next_state = (count < 3) ? B : C;
        C: next_state = (count < 3) ? C : D;
        D: next_state = (count < 3) ? D : E;
        E: next_state = A;
        default: next_state = A;
    endcase
end

always_comb begin
    case (current_state)
        B: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        C: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        D: begin
            if (count == 2) begin
                z_out = (w == 1'b1) ? 1'b1 : 1'b0;
            end else begin
                z_out = 1'b0;
            end
        end
        E: z_out = 1'b0;
        default: z_out = 1'b0;
    endcase
end

assign z = z_out;

endmodule

