module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Internal signals for neighbor count
    reg [255:0] neighbor_count;

    // Function to compute the number of live neighbors for a cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = row + i;
                    int c = col + j;
                    if (r < 0) r = 15;
                    if (r > 15) r = 0;
                    if (c < 0) c = 15;
                    if (c > 15) c = 0;
                    int index = r * 16 + c;
                    if (current_q[index]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute neighbor counts for all cells
    always @(*) begin
        for (int i = 0; i < 16; i = i + 1) begin
            for (int j = 0; j < 16; j = j + 1) begin
                int index = i * 16 + j;
                int neighbors = count_neighbors(i, j);
                if (neighbors == 0 || neighbors == 1) begin
                    next_q[index] = 0;
                end else if (neighbors == 2) begin
                    next_q[index] = current_q[index];
                end else if (neighbors == 3) begin
                    next_q[index] = 1;
                end else begin
                    next_q[index] = 0;
                end
            end
        end
    end

    // Load data into current_q on the rising edge of load
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Assign output
    assign q = current_q;

endmodule

