    always @(y, w) begin
        case ({y, w})
            3'b0000: next_state = 3'b000; // A -> A (w=0)
            3'b0001: next_state = 3'b001; // A -> B (w=1)
            3'b0010: next_state = 3'b010; // B -> C (w=0)
            3'b0011: next_state = 3'b011; // B -> D (w=1)
            3'b0100: next_state = 3'b100; // C -> E (w=0)
            3'b0101: next_state = 3'b011; // C -> D (w=1)
            3'b0110: next_state = 3'b110; // D -> F (w=0)
            3'b0111: next_state = 3'b000; // D -> A (w=1)
            3'b1000: next_state = 3'b100; // E -> E (w=0)
            3'b1001: next_state = 3'b011; // E -> D (w=1)
            3'b1100: next_state = 3'b010; // F -> C (w=0)
            3'b1101: next_state = 3'b011; // F -> D (w=1)
            default: next_state = 3'b000;
        endcase
        Y1 = next_state[1];
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum reg [1:0] {A, B, C, D, E} state_t;

state_t current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

// State transition logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end
        B: begin
            next_state = C;
        end
        C: begin
            next_state = D;
        end
        D: begin
            next_state = E;
        end
        E: begin
            next_state = B;
        end
        default: next_state = A;
    endcase
end

// Output logic
always @(*) begin
    case (current_state)
        A: z = 1'b0;
        B: z = 1'b0;
        C: z = 1'b0;
        D: z = 1'b0;
        E: z = 1'b0;
        default: z = 1'b0;
    endcase
end

// Count logic for w in states C, D, E
reg [2:0] w_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        w_count <= 3'b000;
    end else begin
        if (current_state == B) begin
            w_count <= 3'b000;
        end else if (current_state == E) begin
            w_count <= w_count + 1;
        end
    end
end

// Set z to 1 if exactly two of the last three w values were 1
always @(*) begin
    case (current_state)
        E: begin
            if (w_count == 3'b011 || w_count == 3'b101 || w_count == 3'b110) begin
                z = 1'b1;
            end else begin
                z = 1'b0;
            end
        end
        default: z = 1'b0;
    endcase
end

endmodule

module TopModule (
    input  clock,
    input  a,
    output p,
    output q
);

reg p_reg, q_reg;

always @(posedge clock) begin
    if (a) begin
        p_reg <= 1'b1;
        q_reg <= 1'b0;
    end else begin
        if (p_reg) begin
            p_reg <= 1'b0;
            q_reg <= 1'b1;
        end else begin
            p_reg <= 1'b0;
            q_reg <= 1'b0;
        end
    end
end

assign p = p_reg;
assign q = q_reg;

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Define the size of the grid
    localparam SIZE = 16;

    // Internal register to hold the next state
    reg [255:0] next_q;

    // Function to compute the number of live neighbors for a given cell
    function [3:0] count_neighbors;
        input [255:0] grid;
        input [4:0] row, col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % SIZE;
                    int c = (col + j) % SIZE;
                    if (grid[(r * SIZE) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Compute next state based on current state
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            next_q <= 256'd0;
            for (int i = 0; i < SIZE; i = i + 1) begin
                for (int j = 0; j < SIZE; j = j + 1) begin
                    int neighbors = count_neighbors(q, i, j);
                    if (neighbors == 2) begin
                        next_q[(i * SIZE) + j] = q[(i * SIZE) + j];
                    end else if (neighbors == 3) begin
                        next_q[(i * SIZE) + j] = 1'b1;
                    end
                end
            end
            q <= next_q;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current sensor state
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        // Above s[2]
                        state <= 2'd3;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else begin
                        // Between s[2] and s[1]
                        state <= 2'd2;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Check if the previous level was lower than the current level
    always @(posedge clk) begin
        if (s[2] && !prev_s[2]) begin
            dfr <= 1'b1;
        end else if (!s[2] && prev_s[2]) begin
            dfr <= 1'b0;
        end else if (s[1] && !prev_s[1]) begin
            dfr <= 1'b1;
        end else if (!s[1] && prev_s[1]) begin
            dfr <= 1'b0;
        end else if (s[0] && !prev_s[0]) begin
            dfr <= 1'b1;
        end else if (!s[0] && prev_s[0]) begin
            dfr <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                was_falling <= 1'b1;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                next_state = prev_direction ? WALK_LEFT : WALK_RIGHT;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b0) begin
                // Ignore dig while falling
            end else if (dig && current_state == DIGGING) begin
                // Continue digging
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = prev_direction ? WALK_LEFT : WALK_RIGHT;
            end else if (bump_left || bump_right) begin
                if (current_state == WALK_LEFT) begin
                    next_state = WALK_RIGHT;
                end else if (current_state == WALK_RIGHT) begin
                    next_state = WALK_LEFT;
                end
            end

            // Update current state
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  y,
    input  w,
    output Y1
);

    // State codes: y = 000 (A), 001 (B), 010 (C), 011 (D), 100 (E), 101 (F)
    // y is a 3-bit input, but we only need to implement next-state logic for y[1]

    // Next-state logic for y[1] based on current state (y) and input w
    // Current state is determined by y[2:0], and we compute next state based on transitions

    // State transitions:
    // A (000) --0--> B (001), --1--> A (000)
    // B (001) --0--> C (010), --1--> D (011)
    // C (010) --0--> E (100), --1--> D (011)
    // D (011) --0--> F (101), --1--> A (000)
    // E (100) --0--> E (100), --1--> D (011)
    // F (101) --0--> C (010), --1--> D (011)

    // Determine next state based on current state and input w
    // Compute next y[1] based on the transition

    // Extract current state bits
    wire y2 = y[2];
    wire y1 = y[1];
    wire y0 = y[0];

    // Determine next y[1] based on current state and input w
    assign Y1 = (
        (y2 == 1'b0 && y1 == 1'b0 && y0 == 1'b0) && w == 1'b0 ? 1'b0 : // A -> B
        (y2 == 1'b0 && y1 == 1'b0 && y0 == 1'b0) && w == 1'b1 ? 1'b0 : // A -> A
        (y2 == 1'b0 && y1 == 1'b0 && y0 == 1'b1) && w == 1'b0 ? 1'b1 : // B -> C
        (y2 == 1'b0 && y1 == 1'b0 && y0 == 1'b1) && w == 1'b1 ? 1'b1 : // B -> D
        (y2 == 1'b0 && y1 == 1'b1 && y0 == 1'b0) && w == 1'b0 ? 1'b0 : // C -> E
        (y2 == 1'b0 && y1 == 1'b1 && y0 == 1'b0) && w == 1'b1 ? 1'b1 : // C -> D
        (y2 == 1'b0 && y1 == 1'b1 && y0 == 1'b1) && w == 1'b0 ? 1'b0 : // D -> F
        (y2 == 1'b0 && y1 == 1'b1 && y0 == 1'b1) && w == 1'b1 ? 1'b0 : // D -> A
        (y2 == 1'b1 && y1 == 1'b0 && y0 == 1'b0) && w == 1'b0 ? 1'b0 : // E -> E
        (y2 == 1'b1 && y1 == 1'b0 && y0 == 1'b0) && w == 1'b1 ? 1'b1 : // E -> D
        (y2 == 1'b1 && y1 == 1'b0 && y0 == 1'b1) && w == 1'b0 ? 1'b1 : // F -> C
        (y2 == 1'b1 && y1 == 1'b0 && y0 == 1'b1) && w == 1'b1 ? 1'b1  // F -> D
    );

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate input (high when fr2 is asserted)
// fr1 - nominal flow rate input (high when fr1 is asserted)
// fr0 - nominal flow rate input (high when fr0 is asserted)
// dfr - supplemental flow valve (high when dfr is asserted)
//
// State transitions based on current sensor input and previous sensor input
//
// State transitions:
// 1. When s[2] is asserted (water level above s[2]):
//    - fr2, fr1, fr0 = 0
//    - dfr = 0
//    - Flow rate = 0
//
// 2. When s[1] and s[0] are asserted (water level between s[2] and s[1]):
//    - fr0 = 1, fr1 = 0, fr2 = 0
//    - dfr = 0 (if previous level was not lower)
//    - dfr = 1 (if previous level was lower)
//
// 3. When s[0] is asserted (water level between s[1] and s[0]):
//    - fr0 = 1, fr1 = 1, fr2 = 0
//    - dfr = 0 (if previous level was not lower)
//    - dfr = 1 (if previous level was lower)
//
// 4. When no sensors are asserted (water level below s[0]):
//    - fr0 = 1, fr1 = 1, fr2 = 1
//    - dfr = 0 (if previous level was not lower)
//    - dfr = 1 (if previous level was lower)
//
// Reset condition:
// - All outputs are set to 1 (fr2, fr1, fr0, dfr = 1)
// - Equivalent to water level being low for a long time

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State variables
    reg [2:0] prev_s;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
            prev_s <= 3'b000;
        end else begin
            // Determine current water level and set outputs
            if (s[2]) begin
                // Water level above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end else if (s[1] && !s[0]) begin
                // Water level between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= (prev_s[0] == 1'b0) ? 1'b0 : 1'b1;
            end else if (s[0]) begin
                // Water level between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= (prev_s[0] == 1'b0) ? 1'b0 : 1'b1;
            end else begin
                // Water level below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= (prev_s[0] == 1'b0) ? 1'b0 : 1'b1;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

endmodule

// State Transition Table for TopModule

// States:
// S0: walk_left
// S1: walk_right
// S2: falling (aaah)
// S3: digging

// Inputs: clk, areset, bump_left, bump_right, ground, dig
// Outputs: walk_left, walk_right, aaah, digging

// State | bump_left | bump_right | ground | dig | Next State | walk_left | walk_right | aaah | digging
// S0    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S0    | 1        | 0         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 1        | 1         | 1     | 0  | S1         | 0         | 1          | 0    | 0
// S0    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S0    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S1    | 0        | 1         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 1        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S1    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S1    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S2    | 0        | 0         | 1     | 1  | S2         | 0         | 0          | 1    | 1
// S2    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S2    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 1
// S3    | 0        | 0         | 1     | 0  | S0         | 1         | 0          | 0    | 0
// S3    | 0        | 0         | 1     | 1  | S3         | 0         | 0          | 0    | 1
// S3    | 0        | 0         | 0     | 0  | S2         | 0         | 0          | 1    | 0
// S3    | 0        | 0         | 0     | 1  | S2         | 0         | 0          | 1    | 0

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : 0;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : 0;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S1;
                    else if (!ground) next_state = S2;
                end
            end
            S1: begin
                if (ground) begin
                    if (dig) next_state = S3;
                    else if (bump_left || bump_right) next_state = S0;
                    else if (!ground) next_state = S2;
                end
            end
            S2: begin
                if (ground) next_state = S0;
            end
            S3: begin
                if (!ground) next_state = S2;
                else if (dig) next_state = S3;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (we'll use the previous value of current_state)
            previous_state <= current_state;

            // Output logic based on current state and whether the level increased
            if (current_state == 2'b11) begin // Above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end else if (current_state == 2'b10) begin // Between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end else if (current_state == 2'b01) begin // Between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= (previous_state == 2'b10) ? 1'b1 : 1'b0; // Check if previous level was lower
            end else begin // Below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1 && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == FALLING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
            end else if (dig && current_state == WALK_LEFT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
            end else if (dig && current_state == WALK_RIGHT && ground == 1) begin
                next_state = DIGGING;
                digging <= 1;
            end else if (current_state == DIGGING && ground == 0) begin
                next_state = FALLING;
                aaah <= 1;
                digging <= 0;
            end else if (current_state == DIGGING && ground == 1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1 - prev_direction;
                aaah <= 0;
                digging <= 0;
            end else if (current_state == WALK_LEFT && (bump_left || bump_right)) begin
                next_state = WALK_RIGHT;
                walk_left <= 0;
                walk_right <= 1;
            end else if (current_state == WALK_RIGHT && (bump_left || bump_right)) begin
                next_state = WALK_LEFT;
                walk_left <= 1;
                walk_right <= 0;
            end

            // Update current state
            current_state <= next_state;

            // Handle digging
            if (current_state == DIGGING) begin
                digging <= 1;
            end else begin
                digging <= 0;
            end

            // Handle walking direction
            if (current_state == WALK_LEFT) begin
                walk_left <= 1;
                walk_right <= 0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 0;
                walk_right <= 1;
            end

            // Handle aaah
            if (current_state == FALLING) begin
                aaah <= 1;
            end else begin
                aaah <= 0;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine the current water level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // Indicate all sensors are asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Determine outputs based on current state and previous sensor state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (state)
                3: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                0: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    // Check for bump
                    if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_left) begin
                        next_state = WALK_RIGHT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                DIGGING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                default: next_state = WALK_LEFT;
            endcase

            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end

                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end

                default: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
            endcase
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate input (high when fr2 is asserted)
// fr1 - nominal flow rate input (high when fr1 is asserted)
// fr0 - nominal flow rate input (high when fr0 is asserted)
// dfr - supplemental flow valve (high when dfr is asserted)
//
// State Machine:
// State transitions are based on current sensor input and previous sensor input.
// The state machine tracks the previous sensor state to determine if the level has increased.
//
// State Definitions:
// 0: No sensors asserted (water level below s[0])
// 1: s[0] asserted (water level between s[1] and s[0])
// 2: s[1] and s[0] asserted (water level between s[2] and s[1])
// 3: s[2], s[1], s[0] asserted (water level above s[2])
//
// Transition Logic:
// - On reset, state is 0 (water level below s[0])
// - If the current sensor state is higher than the previous, the level has increased (dfr = 1)
// - If the current sensor state is lower than the previous, the level has decreased (dfr = 0)
// - The nominal flow rate is determined by the current sensor state
//
// Output Logic:
// - State 0: fr2 = 1, fr1 = 1, fr0 = 1, dfr = 0
// - State 1: fr2 = 0, fr1 = 1, fr0 = 1, dfr = 0
// - State 2: fr2 = 0, fr1 = 0, fr0 = 1, dfr = 0
// - State 3: fr2 = 0, fr1 = 0, fr0 = 0, dfr = 0

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definitions
    typedef enum reg [1:0] {
        STATE_0 = 2'b00, // No sensors asserted (water level below s[0])
        STATE_1 = 2'b01, // s[0] asserted (water level between s[1] and s[0])
        STATE_2 = 2'b10, // s[1] and s[0] asserted (water level between s[2] and s[1])
        STATE_3 = 2'b11  // s[2], s[1], s[0] asserted (water level above s[2])
    } state_t;

    state_t current_state, next_state;
    reg [2:0] prev_s;

    // State transition logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= STATE_0;
            prev_s <= 3'b000;
        end else begin
            prev_s <= s;
            case (current_state)
                STATE_0: begin
                    if (s == 3'b001) next_state <= STATE_1;
                    else if (s == 3'b011) next_state <= STATE_2;
                    else if (s == 3'b111) next_state <= STATE_3;
                    else next_state <= STATE_0;
                end
                STATE_1: begin
                    if (s == 3'b011) next_state <= STATE_2;
                    else if (s == 3'b111) next_state <= STATE_3;
                    else if (s == 3'b000) next_state <= STATE_0;
                    else next_state <= STATE_1;
                end
                STATE_2: begin
                    if (s == 3'b111) next_state <= STATE_3;
                    else if (s == 3'b000) next_state <= STATE_0;
                    else if (s == 3'b001) next_state <= STATE_1;
                    else next_state <= STATE_2;
                end
                STATE_3: begin
                    if (s == 3'b000) next_state <= STATE_0;
                    else if (s == 3'b001) next_state <= STATE_1;
                    else if (s == 3'b011) next_state <= STATE_2;
                    else next_state <= STATE_3;
                end
            endcase
            current_state <= next_state;
        end
    end

    // Output logic based on current state
    always @(posedge clk) begin
        case (current_state)
            STATE_0: begin
                fr2 <= 1;
                fr1 <= 1;
                fr0 <= 1;
                dfr <= 0;
            end
            STATE_1: begin
                fr2 <= 0;
                fr1 <= 1;
                fr0 <= 1;
                dfr <= 0;
            end
            STATE_2: begin
                fr2 <= 0;
                fr1 <= 0;
                fr0 <= 1;
                dfr <= 0;
            end
            STATE_3: begin
                fr2 <= 0;
                fr1 <= 0;
                fr0 <= 0;
                dfr <= 0;
            end
        endcase
    end

endmodule

// State Transition Table for TopModule (Moore FSM)

// States:
// S0: Walk Left
// S1: Walk Right
// S2: Falling (aaah)
// S3: Digging

// Inputs:
// clk, areset, bump_left, bump_right, ground, dig

// Outputs:
// walk_left, walk_right, aaah, digging

// State transitions and outputs:

// State S0 (Walk Left)
// Inputs:
// bump_left=1: transition to S1 (walk_right=1)
// bump_right=1: transition to S1 (walk_right=1)
// ground=0: transition to S2 (aaah=1)
// dig=1 and ground=1: transition to S3 (digging=1)
// else: stay in S0 (walk_left=1, aaah=0, digging=0)

// State S1 (Walk Right)
// Inputs:
// bump_left=1: transition to S0 (walk_left=1)
// bump_right=1: transition to S0 (walk_left=1)
// ground=0: transition to S2 (aaah=1)
// dig=1 and ground=1: transition to S3 (digging=1)
// else: stay in S1 (walk_right=1, aaah=0, digging=0)

// State S2 (Falling)
// Inputs:
// ground=1: transition to previous state (walk direction remains)
// else: stay in S2 (aaah=1, digging=0)
// bump_left=1 or bump_right=1: no effect on state or direction

// State S3 (Digging)
// Inputs:
// ground=0: transition to S2 (aaah=1)
// ground=1: stay in S3 (digging=1)
// dig=0: stay in S3 (digging=1)
// else: stay in S3 (digging=1)

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // Walk Left
        S1 = 2'b01, // Walk Right
        S2 = 2'b10, // Falling
        S3 = 2'b11  // Digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1'b1 : (current_state == S1) ? 1'b0 : (current_state == S2 || current_state == S3) ? 1'b0 : 1'b0;
            walk_right <= (current_state == S1) ? 1'b1 : (current_state == S0) ? 1'b0 : (current_state == S2 || current_state == S3) ? 1'b0 : 1'b0;
            aaah <= (current_state == S2) ? 1'b1 : 1'b0;
            digging <= (current_state == S3) ? 1'b1 : 1'b0;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (bump_left || bump_right) next_state = S1;
                else if (!ground) next_state = S2;
                else if (dig && ground) next_state = S3;
            end
            S1: begin
                if (bump_left || bump_right) next_state = S0;
                else if (!ground) next_state = S2;
                else if (dig && ground) next_state = S3;
            end
            S2: begin
                if (ground) next_state = current_state; // Stay in S2 if ground is back
            end
            S3: begin
                if (!ground) next_state = S2;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state based on previous sensor inputs
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (sensor change)
            if (current_state > previous_state) begin
                dfr <= 1'b1;
            end
        end
    end
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT && (bump_left || bump_right)) begin
                next_state = WALK_RIGHT;
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == WALK_RIGHT && (bump_left || bump_right)) begin
                next_state = WALK_LEFT;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end

            // Update state
            current_state <= next_state;

            // Update direction for next state
            if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                prev_direction <= (current_state == WALK_LEFT) ? 1'b1 : 1'b0;
            end
        end
    end

endmodule
